import http from "k6/http";
import { check, fail, sleep } from "k6";

// Generated by Ballast from a scenario graph. Editing this does nothing: the
// graph is what is stored, and this file is written from it again every time.
//
// No options block: Ballast writes the load from the run's profile, and k6
// reads it from the module it runs instead of this one.

const BASE_URL = __ENV.BASE_URL;

export default function () {
  const vars = {};
  let res = null;
  res = http.request("POST", BASE_URL + "/login", "{\"user\":\"tester\"}", {
    headers: { "Content-Type": "application/json" },
    tags: { name: "POST /login" },
  });
  if (res.status >= 400) {
    fail("POST /login returned " + res.status);
  }
  vars["token"] = null;
  try {
    vars["token"] = res.json("access_token");
  } catch (error) {
    vars["token"] = null;
  }
  if (vars["token"] === null || vars["token"] === undefined || vars["token"] === "") {
    fail("could not extract the variable \"token\" from the response body (access_token)");
  }
  sleep(0.5);
  res = http.request("GET", BASE_URL + "/users/" + encodeURIComponent(vars["user"]) + "/orders", null, {
    headers: { "Authorization": "Bearer " + vars["token"] },
    tags: { name: "GET /users/{user}/orders" },
  });
  const passed_ok = (vars["status"] === 200);
  check(passed_ok, { "status == 200": (ok) => ok });
  return;
}
